        date: json['date'] as String,
        files: json['files'] as int,
        bytes: json['bytes'] as int,
        uploads: json['uploads'] as int,
        downloads: json['downloads'] as int,
        egressBytes: json['egressBytes'] as int,
      );

  final String date;
  final int files;
  final int bytes;

  /// Uploads committed that day.
  final int uploads;

  /// Downloads begun that day.
  final int downloads;

  /// Chunk bytes served that day. Counted because on most clouds reads are what cost
  /// money.
  final int egressBytes;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'date': date,
        'files': files,
        'bytes': bytes,
        'uploads': uploads,
        'downloads': downloads,
        'egressBytes': egressBytes,
      };
}

/// How much of a room its host can see, fixed at creation and immutable thereafter.
/// `open`: records are cleartext, searchable and fully audited. `attributed`: record
/// content is sealed, and the host still learns which member acted. `private`: content
/// is sealed and membership is presented in zero knowledge, so the host verifies that
/// a member acted without learning which. Immutable because a downgrade cannot un-see
/// cleartext and an upgrade would protect only what came after while presenting as
/// though it protected everything.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const Visibility(String value) {
  static const Visibility open = Visibility('open');
  static const Visibility attributed = Visibility('attributed');
  static const Visibility private = Visibility('private');

  /// Every value this specification's schema permits.
  static const List<Visibility> values = <Visibility>[
    open,
    attributed,
    private
  ];
}

/// Whether a room keeps its history readable across a membership change, fixed at
/// creation and immutable thereafter — like `Visibility`, and for the same reason: the
/// rungs of an epoch key chain either exist for an epoch or they do not, and no later
/// change of mind can seal key material that was never sealed or unseal what was
/// already severed. `chained`: each advance produces an `EpochLink`, so every member
/// reads the room's whole retained history however long they have been in it — what a
/// **library** wants, at the cost of post-compromise security for record content,
/// since a compromised current key then reaches every retained epoch. `fromJoin`: no
/// rungs are produced, so a member reads only from the epoch their group state is at —
/// what a **stream** wants, and what a room under a strict forward-secrecy obligation
/// wants, at the cost that a joining member finds an empty-looking room and nobody can
/// reread a record once their group state has moved past the epoch it was sealed
/// under. Absent means `chained`; see the prose on why the absent case is the readable
/// one.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RetentionPolicy(String value) {
  static const RetentionPolicy chained = RetentionPolicy('chained');
  static const RetentionPolicy fromJoin = RetentionPolicy('fromJoin');

  /// Every value this specification's schema permits.
  static const List<RetentionPolicy> values = <RetentionPolicy>[
    chained,
    fromJoin
  ];
}

/// HostedRoomLifecycle is a closed set of string values defined by this
/// specification's schema.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const HostedRoomLifecycle(String value) {
  static const HostedRoomLifecycle live = HostedRoomLifecycle('live');
  static const HostedRoomLifecycle lapsed = HostedRoomLifecycle('lapsed');
  static const HostedRoomLifecycle dormant = HostedRoomLifecycle('dormant');
  static const HostedRoomLifecycle reclaimable =
      HostedRoomLifecycle('reclaimable');

  /// Every value this specification's schema permits.
  static const List<HostedRoomLifecycle> values = <HostedRoomLifecycle>[
    live,
    lapsed,
    dormant,
    reclaimable
  ];
}

/// One room, as its host holds it — member for member the `HostedRoom` of
/// vtc/rooms/list/0.1, which defines it inside its own payload schema. Nothing derived
/// from the room's contents, and no member list: the host has none.
class HostedRoom {
  const HostedRoom({
    required this.roomId,
    required this.ownerDid,
    required this.visibility,
    required this.retentionPolicy,
    required this.epoch,
    required this.lifecycle,
    this.epochExpiresAt,
    required this.retentionDays,
    this.mirrorOf,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory HostedRoom.fromJson(Map<String, dynamic> json) => HostedRoom(
        roomId: json['roomId'] as String,
        ownerDid: json['ownerDid'] as String,
        visibility: Visibility(json['visibility'] as String),
        retentionPolicy: RetentionPolicy(json['retentionPolicy'] as String),
        epoch: json['epoch'] as int,
        lifecycle: HostedRoomLifecycle(json['lifecycle'] as String),
        epochExpiresAt: json['epochExpiresAt'] as int?,
        retentionDays: json['retentionDays'] as int,
        mirrorOf: json['mirrorOf'] as String?,
        createdAt: json['createdAt'] as int,
        updatedAt: json['updatedAt'] as int,
      );

  final String roomId;
  final String ownerDid;
  final Visibility visibility;
  final RetentionPolicy retentionPolicy;
  final int epoch;
  final HostedRoomLifecycle lifecycle;
  final int? epochExpiresAt;
  final int retentionDays;
  final String? mirrorOf;
  final int createdAt;
  final int updatedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'roomId': roomId,
        'ownerDid': ownerDid,
        'visibility': visibility.value,
        'retentionPolicy': retentionPolicy.value,
        'epoch': epoch,
        'lifecycle': lifecycle.value,
        if (epochExpiresAt != null) 'epochExpiresAt': epochExpiresAt!,
        'retentionDays': retentionDays,
        if (mirrorOf != null) 'mirrorOf': mirrorOf!,
        'createdAt': createdAt,
        'updatedAt': updatedAt,
      };
}
